import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print('check failed:', e); sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import ast, glob, os
mods = {os.path.basename(f)[:-3] for f in glob.glob('_tools/*.py')}
imps = {}
for f in glob.glob('_tools/*.py'):
    m = os.path.basename(f)[:-3]
    if m.startswith('test_'): continue
    s = set()
    for n in ast.walk(ast.parse(open(f, encoding='utf-8').read())):
        if isinstance(n, ast.Import): s |= {a.name for a in n.names if a.name in mods}
        elif isinstance(n, ast.ImportFrom) and n.module in mods: s.add(n.module)
    imps[m] = s
bad = []
for b, p in (('ql_base', 'ql_'), ('kg_base', 'kg_'), ('bench_core', 'bench_'), ('bl_base', 'bl_'), ('mon_base', 'mon_')):
    bad += [f'{b} -> {x}' for x in imps.get(b, ()) if x.startswith(p) and x != b]
for a in imps:
    for b in imps[a]:
        if a < b and a in imps.get(b, ()) and a[:3] == b[:3] and a[:3] in ('bl_', 'ql_'):
            bad.append(f'{a} <-> {b}')
print('import direction breaks:', bad)
sys.exit(1 if bad else 0)
